const http = require('node:http');
const path = require('node:path');

const fixturesDir = path.join(__dirname, 'fixtures');
const dataFixturesDir = path.join(fixturesDir, 'data');
const staticFixturesDir = path.join(fixturesDir, 'static');

const validDataPath = path.join(dataFixturesDir, 'levels.valid.json');
const invalidJsonDataPath = path.join(dataFixturesDir, 'levels.invalid-json.json');
const invalidStructureDataPath = path.join(dataFixturesDir, 'levels.invalid-structure.json');
const wrongCountDataPath = path.join(dataFixturesDir, 'levels.wrong-count.json');
const missingDataPath = path.join(dataFixturesDir, 'levels.missing.json');
const secretOutsideStaticRoot = path.join(fixturesDir, 'secret.txt');
const repoDataPath = path.join(__dirname, '..', 'data', 'levels.json');
const serverEntryPath = path.join(__dirname, '..', 'server', 'server.js');

// 以原始请求路径发送 HTTP 请求（不做任何客户端归一化），
// 用于覆盖静态托管的路径安全分支。
function rawRequest(origin, rawPath) {
  const { hostname, port } = new URL(origin);
  return new Promise((resolve, reject) => {
    const request = http.get({ hostname, port: Number(port), path: rawPath }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf8')
        });
      });
    });
    request.on('error', reject);
    request.end();
  });
}

module.exports = {
  fixturesDir,
  dataFixturesDir,
  staticFixturesDir,
  validDataPath,
  invalidJsonDataPath,
  invalidStructureDataPath,
  wrongCountDataPath,
  missingDataPath,
  secretOutsideStaticRoot,
  repoDataPath,
  serverEntryPath,
  rawRequest
};
