{"content":"'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');

const { start } = require('../server/server');
const {
  dataFixturesDir,
  staticFixturesDir,
  validDataPath,
  invalidJsonDataPath,
  invalidStructureDataPath,
  wrongCountDataPath,
  missingDataPath
} = require('./helpers');

const DIFFICULTIES = ['简单', '普通', '困难'];

test('GET /api/levels 数据合法时返回 200 与恰好 5 个合法关卡', async () => {
  const instance = await start({ port: 0, dataPath: validDataPath, staticRoot: staticFixturesDir });
  try {
    const response = await fetch(`${instance.origin}/api/levels`);
    assert.strictEqual(response.status, 200);
    assert.strictEqual(response.headers.get('content-type'), 'application/json; charset=utf-8');
    const levels = await response.json();
    assert.ok(Array.isArray(levels), '顶层必须是数组');
    assert.strictEqual(levels.length, 5, '顶层长度必须恰为 5');
    const ids = new Set();
    for (const level of levels) {
      assert.strictEqual(typeof level.id, 'string');
      assert.ok(level.id.length > 0, 'id 必须非空');
      assert.ok(!ids.has(level.id), 'id 必须唯一');
      ids.add(level.id);
      assert.strictEqual(typeof level.name, 'string');
      assert.ok(level.name.length > 0, 'name 必须非空');
      assert.ok(DIFFICULTIES.includes(level.difficulty), 'difficulty 取值必须合法');
      assert.strictEqual(typeof level.unlocked, 'boolean', 'unlocked 必须是布尔值');
    }
    assert.strictEqual(ids.size, 5);
  } finally {
    await instance.stop();
  }
});

const errorCases = [
  { label: '数据文件缺失', dataPath: missingDataPath },
  { label: 'JSON 无法解析', dataPath: invalidJsonDataPath },
  { label: '结构校验失败（字段非法）', dataPath: invalidStructureDataPath },
  { label: '结构校验失败（关卡数量不为 5）', dataPath: wrongCountDataPath }
];

for (const { label, dataPath } of errorCases) {
  test(`GET /api/levels 在${label}时返回 500 LEVEL_DATA_UNAVAILABLE`, async () => {
    const instance = await start({ port: 0, dataPath, staticRoot: staticFixturesDir });
    try {
      const response = await fetch(`${instance.origin}/api/levels`);
      assert.strictEqual(response.status, 500);
      assert.strictEqual(response.headers.get('content-type'), 'application/json; charset=utf-8');
      const body = await response.json();
      assert.deepStrictEqual(Object.keys(body).sort(), ['code', 'message']);
      assert.strictEqual(body.code, 'LEVEL_DATA_UNAVAILABLE');
      assert.strictEqual(typeof body.message, 'string');
      assert.ok(body.message.length > 0, 'message 必须是非空可读消息');
      assert.ok(!body.message.includes(dataFixturesDir), 'message 不得包含绝对路径');
      assert.ok(!body.message.includes('    at '), 'message 不得包含堆栈帧');
    } finally {
      await instance.stop();
    }
  });
}

test('GET /api/levels 在数据文件不可读时返回 500 LEVEL_DATA_UNAVAILABLE', { skip: process.getuid?.() === 0 }, async () => {
  const unreadablePath = path.join(dataFixturesDir, 'levels.unreadable.json');
  await fs.writeFile(unreadablePath, await fs.readFile(validDataPath, 'utf8'));
  await fs.chmod(unreadablePath, 0o000);
  let instance;
  try {
    instance = await start({ port: 0, dataPath: unreadablePath, staticRoot: staticFixturesDir });
    const response = await fetch(`${instance.origin}/api/levels`);
    assert.strictEqual(response.status, 500);
    const body = await response.json();
    assert.strictEqual(body.code, 'LEVEL_DATA_UNAVAILABLE');
    assert.ok(!body.message.includes(dataFixturesDir), 'message 不得包含绝对路径');
    assert.ok(!body.message.includes('    at '), 'message 不得包含堆栈帧');
  } finally {
    if (instance) await instance.stop();
    await fs.chmod(unreadablePath, 0o644);
    await fs.rm(unreadablePath, { force: true });
  }
});
