{"content":"'use strict';

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const HOST = '127.0.0.1';
const DEFAULT_PORT = 3000;
const LEVEL_COUNT = 5;
const VALID_DIFFICULTIES = ['简单', '普通', '困难'];

const PROJECT_ROOT = path.resolve(__dirname, '..');
const DEFAULT_DATA_PATH = path.join(PROJECT_ROOT, 'data', 'levels.json');
const DEFAULT_STATIC_ROOT = path.join(PROJECT_ROOT, 'web');

const STATIC_CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2'
};

function validateLevels(payload) {
  if (!Array.isArray(payload)) return '关卡数据必须是数组';
  if (payload.length !== LEVEL_COUNT) return `关卡数据必须恰好包含 ${LEVEL_COUNT} 个关卡`;
  const seenIds = new Set();
  for (const level of payload) {
    if (level === null || typeof level !== 'object' || Array.isArray(level)) {
      return '每个关卡必须是对象';
    }
    if (typeof level.id !== 'string' || level.id === '') return '关卡 id 必须是非空字符串';
    if (seenIds.has(level.id)) return `关卡 id 重复：${level.id}`;
    seenIds.add(level.id);
    if (typeof level.name !== 'string' || level.name === '') return '关卡 name 必须是非空字符串';
    if (!VALID_DIFFICULTIES.includes(level.difficulty)) {
      return '关卡 difficulty 必须是 简单、普通 或 困难';
    }
    if (typeof level.unlocked !== 'boolean') return '关卡 unlocked 必须是布尔值';
  }
  return null;
}

async function readLevels(dataPath) {
  let raw;
  try {
    raw = await fs.promises.readFile(dataPath, 'utf8');
  } catch (err) {
    return { error: '关卡数据不可用：数据文件缺失或无法读取' };
  }
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (err) {
    return { error: '关卡数据不可用：数据文件不是有效的 JSON' };
  }
  const problem = validateLevels(payload);
  if (problem) return { error: `关卡数据不可用：${problem}` };
  return { levels: payload };
}

function sendJson(res, statusCode, body) {
  const serialized = Buffer.from(JSON.stringify(body), 'utf8');
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': serialized.length
  });
  res.end(serialized);
}

function sendText(res, statusCode, message) {
  const body = Buffer.from(message, 'utf8');
  res.writeHead(statusCode, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': body.length
  });
  res.end(body);
}

async function handleLevelsRequest(res, dataPath) {
  const result = await readLevels(dataPath);
  if (result.error) {
    sendJson(res, 500, { code: 'LEVEL_DATA_UNAVAILABLE', message: result.error });
    return;
  }
  sendJson(res, 200, result.levels);
}

function serveStatic(req, res, pathname, staticRoot) {
  if (req.method !== 'GET') {
    sendText(res, 405, '静态资源仅支持 GET 请求');
    return;
  }
  let decoded;
  try {
    decoded = decodeURIComponent(pathname);
  } catch (err) {
    sendText(res, 400, '请求路径编码无效');
    return;
  }
  if (decoded === '/') decoded = '/index.html';
  const rootDir = path.resolve(staticRoot);
  const target = path.normalize(path.join(rootDir, decoded));
  if (!target.startsWith(rootDir + path.sep)) {
    sendText(res, 403, '禁止访问该路径');
    return;
  }
  fs.promises
    .readFile(target)
    .then((content) => {
      const contentType = STATIC_CONTENT_TYPES[path.extname(target).toLowerCase()] || 'application/octet-stream';
      res.writeHead(200, { 'Content-Type': contentType, 'Content-Length': content.length });
      res.end(content);
    })
    .catch(() => sendText(res, 404, '静态资源不存在'));
}

function createRequestHandler(options = {}) {
  const dataPath = path.resolve(options.dataPath || DEFAULT_DATA_PATH);
  const staticRoot = path.resolve(options.staticRoot || DEFAULT_STATIC_ROOT);
  return (req, res) => {
    let pathname;
    try {
      pathname = new URL(req.url, `http://${HOST}`).pathname;
    } catch (err) {
      sendText(res, 400, '请求路径无效');
      return;
    }
    if (pathname === '/api/levels') {
      if (req.method === 'GET') {
        handleLevelsRequest(res, dataPath).catch(() => {
          sendJson(res, 500, { code: 'LEVEL_DATA_UNAVAILABLE', message: '关卡数据不可用' });
        });
      } else {
        sendJson(res, 405, { code: 'METHOD_NOT_ALLOWED', message: '该 API 路径不支持此 HTTP 方法' });
      }
      return;
    }
    if (pathname.startsWith('/api/')) {
      sendJson(res, 404, { code: 'NOT_FOUND', message: '未知的 API 路径' });
      return;
    }
    serveStatic(req, res, pathname, staticRoot);
  };
}

function createServer(options = {}) {
  return http.createServer(createRequestHandler(options));
}

function resolvePort(port) {
  if (port !== undefined) return port;
  const raw = process.env.PORT;
  if (raw !== undefined && raw !== '') {
    const fromEnv = Number(raw);
    if (Number.isInteger(fromEnv) && fromEnv >= 0) return fromEnv;
  }
  return DEFAULT_PORT;
}

async function start(options = {}) {
  const { port, dataPath, staticRoot } = options;
  const server = createServer({ dataPath, staticRoot });
  await new Promise((resolve, reject) => {
    const onError = (err) => reject(err);
    server.once('error', onError);
    server.listen(resolvePort(port), HOST, () => {
      server.removeListener('error', onError);
      resolve();
    });
  });
  server.on('error', (err) => {
    console.error(`服务器错误：${err.message}`);
  });
  const { address, port: listeningPort } = server.address();
  return {
    origin: `http://${address}:${listeningPort}`,
    port: listeningPort,
    dataPath: path.resolve(dataPath || DEFAULT_DATA_PATH),
    staticRoot: path.resolve(staticRoot || DEFAULT_STATIC_ROOT),
    stop: () =>
      new Promise((resolve, reject) => {
        if (typeof server.closeAllConnections === 'function') server.closeAllConnections();
        server.close((err) => (err ? reject(err) : resolve()));
      })
  };
}

module.exports = { createServer, start };

if (require.main === module) {
  start()
    .then(({ origin }) => {
      console.log(`服务器已启动：${origin}`);
    })
    .catch((err) => {
      console.error(`服务器启动失败：${err.message}`);
      process.exitCode = 1;
    });
}
