34	function validateLevels(payload) {
35	  if (!Array.isArray(payload)) return '关卡数据必须是数组';
36	  if (payload.length !== LEVEL_COUNT) return `关卡数据必须恰好包含 ${LEVEL_COUNT} 个关卡`;
37	  const seenIds = new Set();
38	  for (const level of payload) {
39	    if (level === null || typeof level !== 'object' || Array.isArray(level)) {
40	      return '每个关卡必须是对象';
41	    }
42	    if (typeof level.id !== 'string' || level.id === '') return '关卡 id 必须是非空字符串';
43	    if (seenIds.has(level.id)) return `关卡 id 重复：${level.id}`;
44	    seenIds.add(level.id);
45	    if (typeof level.name !== 'string' || level.name === '') return '关卡 name 必须是非空字符串';
