72	function sendJson(res, statusCode, body) {
73	  const serialized = Buffer.from(JSON.stringify(body), 'utf8');
74	  res.writeHead(statusCode, {
75	    'Content-Type': 'application/json; charset=utf-8',
76	    'Content-Length': serialized.length
77	  });
78	  res.end(serialized);
79	}
80	
81	function sendText(res, statusCode, message) {
82	  const body = Buffer.from(message, 'utf8');
83	  res.writeHead(statusCode, {
84	    'Content-Type': 'text/plain; charset=utf-8',
85	    'Content-Length': body.length
86	  });
87	  res.end(body);
88	}
