90	async function handleLevelsRequest(res, dataPath) {
91	  const result = await readLevels(dataPath);
92	  if (result.error) {
93	    sendJson(res, 500, { code: 'LEVEL_DATA_UNAVAILABLE', message: result.error });
94	    return;
95	  }
96	  sendJson(res, 200, result.levels);
97	}
98	
99	function serveStatic(req, res, pathname, staticRoot) {
100	  if (req.method !== 'GET') {
101	    sendText(res, 405, '静态资源仅支持 GET 请求');
102	    return;
103	  }
104	  let decoded;
105	  try {
106	    decoded = decodeURIComponent(pathname);
107	  } catch (err) {
108	    sendText(res, 400, '请求路径编码无效');
109	    return;
110	  }
111	  if (decoded === '/') decoded = '/index.html';
112	  const rootDir = path.resolve(staticRoot);
113	  const target = path.normalize(path.join(rootDir, decoded));
114	  if (!target.startsWith(rootDir + path.sep)) {
115	    sendText(res, 403, '禁止访问该路径');
116	    return;
117	  }
118	  fs.promises
119	    .readFile(target)
120	    .then((content) => {
121	      const contentType = STATIC_CONTENT_TYPES[path.extname(target).toLowerCase()] || 'application/octet-stream';
122	      res.writeHead(200, { 'Content-Type': contentType, 'Content-Length': content.length });
123	      res.end(content);
124	    })
125	    .catch(() => sendText(res, 404, '静态资源不存在'));
126	}
127	
128	function createRequestHandler(options = {}) {
129	  const dataPath = path.resolve(options.dataPath || DEFAULT_DATA_PATH);
130	  const staticRoot = path.resolve(options.staticRoot || DEFAULT_STATIC_ROOT);
131	  return (req, res) => {
132	    let pathname;
133	    try {
134	      pathname = new URL(req.url, `http://${HOST}`).pathname;
135	    } catch (err) {
136	      sendText(res, 400, '请求路径无效');
137	      return;
138	    }
139	    if (pathname === '/api/levels') {
140	      if (req.method === 'GET') {
141	        handleLevelsRequest(res, dataPath).catch(() => {
142	          sendJson(res, 500, { code: 'LEVEL_DATA_UNAVAILABLE', message: '关卡数据不可用' });
143	        });
144	      } else {
145	        sendJson(res, 405, { code: 'METHOD_NOT_ALLOWED', message: '该 API 路径不支持此 HTTP 方法' });
146	      }
147	      return;
148	    }
149	    if (pathname.startsWith('/api/')) {
150	      sendJson(res, 404, { code: 'NOT_FOUND', message: '未知的 API 路径' });
151	      return;
152	    }
153	    serveStatic(req, res, pathname, staticRoot);
154	  };
155	}
156	
157	function createServer(options = {}) {
158	  return http.createServer(createRequestHandler(options));
159	}
160	
161	function resolvePort(port) {
162	  if (port !== undefined) return port;
163	  const raw = process.env.PORT;
164	  if (raw !== undefined && raw !== '') {
165	    const fromEnv = Number(raw);
166	    if (Number.isInteger(fromEnv) && fromEnv >= 0) return fromEnv;
167	  }
168	  return DEFAULT_PORT;
169	}
170	
171	async function start(options = {}) {
172	  const { port, dataPath, staticRoot } = options;
173	  const server = createServer({ dataPath, staticRoot });
174	  await new Promise((resolve, reject) => {
175	    const onError = (err) => reject(err);
176	    server.once('error', onError);
177	    server.listen(resolvePort(port), HOST, () => {
178	      server.removeListener('error', onError);
179	      resolve();
180	    });
181	  });
182	  server.on('error', (err) => {
183	    console.error(`服务器错误：${err.message}`);
184	  });
185	  const { address, port: listeningPort } = server.address();
186	  return {
187	    origin: `http://${address}:${listeningPort}`,
188	    port: listeningPort,
189	    dataPath: path.resolve(dataPath || DEFAULT_DATA_PATH),
190	    staticRoot: path.resolve(staticRoot || DEFAULT_STATIC_ROOT),
191	    stop: () =>
192	      new Promise((resolve, reject) => {
193	        if (typeof server.closeAllConnections === 'function') server.closeAllConnections();
194	        server.close((err) => (err ? reject(err) : resolve()));
195	      })
196	  };
197	}
198	
199	module.exports = { createServer, start };
200	
201	if (require.main === module) {
202	  start()
203	    .then(({ origin }) => {
204	      console.log(`服务器已启动：${origin}`);
205	    })
206	    .catch((err) => {
207	      console.error(`服务器启动失败：${err.message}`);
208	      process.exitCode = 1;
209	    });
210	}

