{"content":"'use strict';

const CONTAINER_IDS = ['loading', 'level-list', 'error-message'];

function createStubElement(tagName) {
  const element = {
    tagName: String(tagName).toUpperCase(),
    children: [],
    parentElement: null,
    textContent: '',
    className: '',
    disabled: false,
    hidden: false,
    listeners: {},
    attributes: {},
    appendChild(child) {
      child.parentElement = element;
      element.children.push(child);
      return child;
    },
    setAttribute(name, value) {
      element.attributes[name] = String(value);
      if (name === 'class') element.className = String(value);
    },
    getAttribute(name) {
      return name in element.attributes ? element.attributes[name] : null;
    },
    addEventListener(type, handler) {
      (element.listeners[type] = element.listeners[type] || []).push(handler);
    },
    click() {
      for (const handler of element.listeners.click || []) handler({});
    }
  };
  return element;
}

function createStubDocument() {
  const elements = new Map();
  for (const id of CONTAINER_IDS) {
    const container = createStubElement('div');
    container.id = id;
    elements.set(id, container);
  }
  return {
    elements,
    getElementById(id) {
      return elements.get(id) || null;
    },
    createElement(tagName) {
      return createStubElement(tagName);
    }
  };
}

function fetchStub(payload) {
  return async function fetchImpl(url) {
    fetchImpl.lastUrl = url;
    fetchImpl.callCount = (fetchImpl.callCount || 0) + 1;
    return {
      ok: true,
      status: 200,
      json: async () => payload
    };
  };
}

function rejectingFetchStub(error) {
  return async function fetchImpl() {
    fetchImpl.callCount = (fetchImpl.callCount || 0) + 1;
    throw error;
  };
}

function statusFetchStub(status) {
  return async function fetchImpl(url) {
    fetchImpl.lastUrl = url;
    fetchImpl.callCount = (fetchImpl.callCount || 0) + 1;
    return {
      ok: status >= 200 && status < 300,
      status,
      json: async () => {
        throw new Error('响应体不是 JSON');
      }
    };
  };
}

function validLevels() {
  return [
    { id: 'level-1', name: '木叶村报到', difficulty: '简单', unlocked: true },
    { id: 'level-2', name: '忍者学校训练', difficulty: '简单', unlocked: true },
    { id: 'level-3', name: '死亡森林演习', difficulty: '普通', unlocked: false },
    { id: 'level-4', name: '中忍考试预选', difficulty: '普通', unlocked: false },
    { id: 'level-5', name: '晓组织来袭', difficulty: '困难', unlocked: false }
  ];
}

module.exports = {
  CONTAINER_IDS,
  createStubDocument,
  fetchStub,
  rejectingFetchStub,
  statusFetchStub,
  validLevels
};
