{"content":"'use strict';

const LEVEL_COUNT = 5;
const VALID_DIFFICULTIES = ['简单', '普通', '困难'];

const MESSAGES = {
  network: '关卡加载失败：网络异常，请检查网络后重试。',
  http: '关卡加载失败：服务暂时不可用，请稍后重试。',
  responseFormat: '关卡加载失败：服务器响应格式无效。',
  levelData: '关卡加载失败：关卡数据无效。'
};

function validateLevels(payload) {
  if (!Array.isArray(payload)) return MESSAGES.levelData;
  if (payload.length !== LEVEL_COUNT) return MESSAGES.levelData;
  const seenIds = new Set();
  for (const level of payload) {
    if (level === null || typeof level !== 'object' || Array.isArray(level)) return MESSAGES.levelData;
    if (typeof level.id !== 'string' || level.id === '') return MESSAGES.levelData;
    if (seenIds.has(level.id)) return MESSAGES.levelData;
    seenIds.add(level.id);
    if (typeof level.name !== 'string' || level.name === '') return MESSAGES.levelData;
    if (!VALID_DIFFICULTIES.includes(level.difficulty)) return MESSAGES.levelData;
    if (typeof level.unlocked !== 'boolean') return MESSAGES.levelData;
  }
  return null;
}

function renderLevelList(doc, list, levels) {
  while (list.children.length > 0) {
    list.children.pop();
  }
  for (const level of levels) {
    const item = doc.createElement('li');
    item.className = level.unlocked ? 'level-item' : 'level-item locked';
    const action = doc.createElement('button');
    action.type = 'button';
    action.className = 'level-action';
    action.textContent = level.unlocked
      ? `${level.name}（难度：${level.difficulty}）`
      : `【已锁定】${level.name}（难度：${level.difficulty}）`;
    if (!level.unlocked) {
      action.disabled = true;
    }
    item.appendChild(action);
    list.appendChild(item);
  }
}

async function initLevelSelect(options = {}) {
  const doc = options.document || (typeof document !== 'undefined' ? document : null);
  const fetchImpl = options.fetchImpl || (typeof fetch !== 'undefined' ? fetch.bind(globalThis) : null);
  if (!doc || !fetchImpl) {
    throw new Error('initLevelSelect 需要 document 与 fetch 环境');
  }
  const loading = doc.getElementById('loading');
  const list = doc.getElementById('level-list');
  const errorBox = doc.getElementById('error-message');

  loading.hidden = false;
  list.hidden = true;
  errorBox.hidden = true;
  errorBox.textContent = '';

  let levels;
  try {
    const response = await fetchImpl('/api/levels');
    if (!response.ok) {
      errorBox.textContent = MESSAGES.http;
      errorBox.hidden = false;
      loading.hidden = true;
      return;
    }
    let payload;
    try {
      payload = await response.json();
    } catch (err) {
      errorBox.textContent = MESSAGES.responseFormat;
      errorBox.hidden = false;
      loading.hidden = true;
      return;
    }
    const problem = validateLevels(payload);
    if (problem) {
      errorBox.textContent = problem;
      errorBox.hidden = false;
      loading.hidden = true;
      return;
    }
    levels = payload;
  } catch (err) {
    errorBox.textContent = MESSAGES.network;
    errorBox.hidden = false;
    loading.hidden = true;
    return;
  }

  loading.hidden = true;
  list.hidden = false;
  renderLevelList(doc, list, levels);
}

if (typeof window !== 'undefined') {
  window.initLevelSelect = initLevelSelect;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { initLevelSelect };
}
