11	};
12	
13	function validateLevels(payload) {
14	  if (!Array.isArray(payload)) return MESSAGES.levelData;
15	  if (payload.length !== LEVEL_COUNT) return MESSAGES.levelData;
16	  const seenIds = new Set();
17	  for (const level of payload) {
18	    if (level === null || typeof level !== 'object' || Array.isArray(level)) return MESSAGES.levelData;
19	    if (typeof level.id !== 'string' || level.id === '') return MESSAGES.levelData;
20	    if (seenIds.has(level.id)) return MESSAGES.levelData;
21	    seenIds.add(level.id);
22	    if (typeof level.name !== 'string' || level.name === '') return MESSAGES.levelData;
23	    if (!VALID_DIFFICULTIES.includes(level.difficulty)) return MESSAGES.levelData;
24	    if (typeof level.unlocked !== 'boolean') return MESSAGES.levelData;
25	  }
26	  return null;
27	}
28	
29	function renderLevelList(doc, list, levels) {
30	  while (list.children.length > 0) {
31	    list.children.pop();
32	  }
33	  for (const level of levels) {
34	    const item = doc.createElement('li');
35	    item.className = level.unlocked ? 'level-item' : 'level-item locked';
36	    const action = doc.createElement('button');
37	    action.type = 'button';
38	    action.className = 'level-action';
39	    action.textContent = level.unlocked
40	      ? `${level.name}（难度：${level.difficulty}）`
41	      : `【已锁定】${level.name}（难度：${level.difficulty}）`;
42	    if (!level.unlocked) {
43	      action.disabled = true;
44	    }
45	    item.appendChild(action);
46	    list.appendChild(item);
47	  }
48	}
49	
50	async function initLevelSelect(options = {}) {
51	  const doc = options.document || (typeof document !== 'undefined' ? document : null);
52	  const fetchImpl = options.fetchImpl || (typeof fetch !== 'undefined' ? fetch.bind(globalThis) : null);
53	  if (!doc || !fetchImpl) {
54	    throw new Error('initLevelSelect 需要 document 与 fetch 环境');
55	  }
56	  const loading = doc.getElementById('loading');
57	  const list = doc.getElementById('level-list');
58	  const errorBox = doc.getElementById('error-message');
59	
60	  loading.hidden = false;
61	  list.hidden = true;
62	  errorBox.hidden = true;
63	  errorBox.textContent = '';
64	
65	  let levels;
66	  try {
67	    const response = await fetchImpl('/api/levels');
68	    if (!response.ok) {
69	      errorBox.textContent = MESSAGES.http;
70	      errorBox.hidden = false;
71	      loading.hidden = true;
72	      return;
73	    }
74	    let payload;
75	    try {
76	      payload = await response.json();
77	    } catch (err) {
78	      errorBox.textContent = MESSAGES.responseFormat;
79	      errorBox.hidden = false;
80	      loading.hidden = true;
81	      return;
82	    }
83	    const problem = validateLevels(payload);
84	    if (problem) {
85	      errorBox.textContent = problem;
86	      errorBox.hidden = false;
87	      loading.hidden = true;
88	      return;
