  const instance = await startDefaultServer();
  try {
    const response = await fetch(`${instance.origin}/`);
    assert.strictEqual(response.status, 200);
    assert.strictEqual(response.headers.get('content-type'), 'text/html; charset=utf-8');
    const html = await response.text();
    assert.ok(html.includes('id="loading"'), '必须包含 id=loading 容器标记');
    assert.ok(html.includes('id="level-list"'), '必须包含 id=level-list 容器标记');
    assert.ok(html.includes('id="error-message"'), '必须包含 id=error-message 容器标记');
    assert.match(
      html,
      /<script[^>]+src="level-select\.js"/,
      '必须包含指向 web/level-select.js（静态路径 level-select.js）的 script 引用'
    );
  } finally {
    await instance.stop();
  }
});

test('经静态路径获取 web/level-select.js 返回 200 且源码以相对路径引用 /api/levels', async () => {
  const instance = await startDefaultServer();
  try {
    const response = await fetch(`${instance.origin}/level-select.js`);
