    assert.ok(
      response.headers.get('content-type').startsWith('text/javascript'),
      '脚本响应 Content-Type 必须是 JavaScript'
    );
    const source = await response.text();
    assert.match(source, /['"]\/api\/levels['"]/u, '源码必须以相对路径 /api/levels 引用关卡 API');
    assert.ok(
      !/['"]https?:\/\/[^'"]*\/api\/levels/.test(source),
      '对 /api/levels 的引用不得是绝对 URL'
    );
  } finally {
    await instance.stop();
  }
});
