const { test } = require('node:test');
const assert = require('node:assert/strict');

const { startDefaultServer, EXPECTED_LEVEL_COUNT, VALID_DIFFICULTIES } = require('./helpers');

test('默认配置启动后 GET /api/levels 返回 200 JSON 且为恰好 5 个字段合法的关卡', async () => {
  const instance = await startDefaultServer();
  try {
    const response = await fetch(`${instance.origin}/api/levels`);
    assert.strictEqual(response.status, 200);
    assert.strictEqual(response.headers.get('content-type'), 'application/json; charset=utf-8');
    const levels = await response.json();
    assert.ok(Array.isArray(levels), '顶层必须是数组');
    assert.strictEqual(levels.length, EXPECTED_LEVEL_COUNT, `顶层长度必须恰为 ${EXPECTED_LEVEL_COUNT}`);
    const ids = new Set();
    for (const level of levels) {
      assert.strictEqual(typeof level.id, 'string', 'id 必须是字符串');
      assert.ok(level.id.length > 0, 'id 必须是非空字符串');
      assert.ok(!ids.has(level.id), 'id 必须唯一');
      ids.add(level.id);
      assert.strictEqual(typeof level.name, 'string', 'name 必须是字符串');
      assert.ok(level.name.length > 0, 'name 必须是非空字符串');
      assert.ok(VALID_DIFFICULTIES.includes(level.difficulty), 'difficulty 必须是 简单、普通 或 困难');
      assert.strictEqual(typeof level.unlocked, 'boolean', 'unlocked 必须是布尔值');
    }
    assert.strictEqual(ids.size, EXPECTED_LEVEL_COUNT);
  } finally {
    await instance.stop();
